"""Real headless Chromium smoke; synthetic DATA ONLY, real browser interactions."""
from pathlib import Path
from playwright.sync_api import sync_playwright, expect
import subprocess
import json

ROOT=Path(__file__).resolve().parents[1]
EVIDENCE=ROOT/'evidence'

# Fixture generated by the app's actual core module; never represented as native data.
GEN="""import {makeSyntheticCapture} from './core.mjs'; console.log(JSON.stringify(makeSyntheticCapture({scenario:'SYNTHETIC_A',shots:12})));"""
def generated_data():
    output=subprocess.run(['node','--input-type=module','-e',GEN],cwd=ROOT,capture_output=True,text=True,check=True)
    receipt,frames,objects=json.loads(output.stdout)
    return [{'name':n,'mimeType':'application/json' if n.endswith('json') else 'text/csv','buffer':txt.encode('utf8')}
            for n,txt in [('receipt.json',receipt),('frames.csv',frames),('objects.csv',objects)]]

def main():
    EVIDENCE.mkdir(exist_ok=True)
    fixture=generated_data()
    successes=[]
    html=(ROOT/'perfview-standalone.html').read_text(encoding='utf8')
    with sync_playwright() as p:
        import os
        executable=os.environ.get('PLAYWRIGHT_CHROMIUM_EXECUTABLE')
        if not executable and Path('/usr/bin/chromium').exists(): executable='/usr/bin/chromium'
        opts={'headless':True}
        if executable: opts['executable_path']=executable
        if os.name!='nt': opts['args']=['--no-sandbox']
        browser=p.chromium.launch(**opts)
        for width,height in [(1280,720),(1920,1080),(720,900)]:
            page=browser.new_page(viewport={'width':width,'height':height})
            errors=[]
            page.on('pageerror',lambda err:errors.append(str(err)))
            page.goto('about:blank')
            page.set_content(html,wait_until='load')
            assert page.locator('#analysis').is_hidden(), 'analysis must start closed'
            page.locator('#demo').click()
            assert page.get_by_text('DEMO — WYŁĄCZNIE SYNTETYCZNE').is_visible()
            assert page.locator('#timeline tr').count()==12
            assert page.locator('.metric').count()==8
            assert page.get_by_text('METADANE ZGODNE — PORÓWNANIE EKSPLORACYJNE').is_visible()
            assert page.evaluate('document.documentElement.scrollWidth <= innerWidth'), 'horizontal overflow'
            assert not errors, errors
            page.screenshot(path=str(EVIDENCE/f'demo_{width}x{height}.png'),full_page=True)
            successes.append(f'demo {width}x{height} rendered, no JS errors/no overflow, 8 metrics + 12 rows')
            if width==1280:
                # Original R1 provenance leak RED: demo A+B; replacing ONLY A
                # marked both as non-demo while retaining synthetic B.
                page.locator('#filesA').set_input_files(fixture)
                expect(page.locator('.metric')).to_have_count(4,timeout=10000)
                assert page.locator('#stateB').inner_text()=='Nie zaimportowano'
                assert page.get_by_text('PLIKI NIEZWERYFIKOWANE NATYWNIE').is_visible()
                assert 'DEMO' not in page.locator('#provenance').inner_text()
                successes.append('demo -> import only A clears both synthetic captures; no mixed provenance')
                page.locator('#demo').click()
                page.locator('#filesB').set_input_files(fixture)
                expect(page.locator('.metric')).to_have_count(4,timeout=10000)
                assert page.locator('#stateA').inner_text()=='Nie zaimportowano'
                successes.append('demo -> import only B clears demo A; no mixed provenance')
                page.locator('#reset').click()
                assert page.locator('#analysis').is_hidden()
                page.locator('#filesA').set_input_files(fixture)
                expect(page.locator('#stateA')).to_contain_text('Zaimportowano',timeout=10000)
                assert page.locator('.metric').count()==4
                assert page.get_by_text('PLIKI NIEZWERYFIKOWANE NATYWNIE').is_visible()
                successes.append('real Chromium file picker import of 3 source-shaped files: 1 session, not native acceptance')
                invalid=[{**f} for f in fixture]
                invalid[0]={**invalid[0],'buffer':invalid[0]['buffer'].replace(b'"capture_complete": true',b'"capture_complete": false')}
                # Safe fallback: directly corrupt original receipt schema as UTF-8 JSON if JSON compact.
                invalid[0]['buffer']=json.dumps({**json.loads(fixture[0]['buffer']),'capture_complete':False}).encode()
                page.locator('#filesB').set_input_files(invalid)
                expect(page.locator('#error')).to_contain_text('incomplete capture',timeout=10000)
                assert page.locator('.metric').count()==4
                assert not errors,errors
                successes.append('corrupt receipt refused, valid A session remains readable; no browser JS error')
                page.locator('#filesB').set_input_files(fixture)
                expect(page.locator('.metric')).to_have_count(8,timeout=10000)
                successes.append('recovery from invalid B to valid B; comparison visible')
            page.close()
        browser.close()
    (EVIDENCE/'browser_log.txt').write_text('\n'.join(successes)+'\n',encoding='utf8')
    print('\n'.join('BROWSER PASS: '+x for x in successes))
    print('BROWSER CASES:',len(successes))

if __name__=='__main__':main()
